patch.diff:
--- a/contract_n.sol
+++ b/contract_n.sol
@@ -21,6 +21,11 @@
     ///         for every ERC20-shaped token the community might donate, including
     ///         ones that do not strictly follow the standard's return-value rules.
     function sweep(address token, uint256 amount) external onlyOwner {
-        IToken(token).transfer(owner, amount);
+        (bool success, bytes memory data) = token.call(
+            abi.encodeWithSelector(IToken.transfer.selector, owner, amount)
+        );
+        // Empty returndata (non-standard tokens, e.g. USDT) counts as success;
+        // if data IS returned, it must decode to `true`.
+        require(success && (data.length == 0 || abi.decode(data, (bool))), "transfer failed");
     }
 }
